extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var master_idx := AudioServer.get_bus_index("Master")
	var music_idx := AudioServer.get_bus_index("Music")
	var sfx_idx := AudioServer.get_bus_index("SFX")
	check("bus_master", master_idx != -1, "Il bus 'Master' deve esistere nel progetto")
	check("bus_music", music_idx != -1, "Il bus 'Music' deve esistere nel progetto")
	check("bus_sfx", sfx_idx != -1, "Il bus 'SFX' deve esistere nel progetto")

	var runner := await instantiate_scene("res://test_runner.tscn")
	check("runner_ok", runner != null, "La scena test_runner.tscn deve potersi istanziare ed eseguire senza errori")

	var credits_sc := await instantiate_scene("res://credits.tscn")
	if check("credits_sc_ok", credits_sc != null, "La scena credits.tscn deve potersi istanziare"):
		await wait_frames(2)
		var labels := find_all_by_class(credits_sc, "Label")
		var total_text := ""
		for l in labels:
			total_text += (l as Label).text + " "
		check("credits_content", total_text.length() > 15, "La schermata dei crediti deve leggere e mostrare il contenuto dal file res://credits.json")

	var settings_sc := await instantiate_scene("res://settings.tscn")
	if check("settings_sc_ok", settings_sc != null, "La scena settings.tscn deve potersi istanziare"):
		await wait_frames(2)
		var sliders := find_all_by_class(settings_sc, "HSlider")
		check("sliders_count", sliders.size() >= 3, "La scena impostazioni deve contenere almeno 3 HSlider per i volumi")
		check("settings_file", FileAccess.file_exists("user://settings.json"), "Le impostazioni devono essere salvate nel file user://settings.json")

